Vamos fazer isso de forma **simplificada, porém funcional**, usando um algoritmo real de compressão: o **run-length encoding (RL)** — uma técnica que é simples, eficiente para textos com repetições de caracteres e facilmente reverter.

---

### ✅ Objetivo
- Ler um arquivo de texto.
- Comprimir os bytes usando **run-length encoding (RL)**.
- Armazenar os dados comprimidos em um array C++.
- Recuperar os bytes originais a partir dos comprimidos.

---

## 📦 1. Código em C++ completo: Comprimir, Exportar em Array e Ler de volta

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <cctype>

// Função para reverter (decompilar) os dados comprimidos usando algorítmo RL
std::vector<char> decompressVector(const std::vector<char>& compressed) {
    std::vector<char> original;
    int i = 0;
    while (i < compressed.size()) {
        unsigned char count_char = compressed[i++];
        unsigned char count = compressed[i++];
        while (count > 0) {
            original.push_back(count_char);
            count--;
        }
    }
    return original;
}
// ----------------------------------------------------------------

int main() {
    std::ifstream inputFile("teste.txt");
    std::ofstream outputFile("comprimido.txt");

    // Verificar arquivos
    if (!inputFile.is_open()) {
        std::cerr << "Erro: Não foi possível abrir o arquivo de entrada." << std::endl;
        return 1;
    }

    // Ler todo o arquivo de texto
    std::string content((std::istreambuf_iterator<char>(inputFile), std::istreambuf_iterator<char>()));
    inputFile.close();

    if (content.empty()) {
        std::cerr << "O arquivo de entrada está vazio." << std::endl;
        return 1;
    }

    std::vector<unsigned char> original;
    for (char c : content) {
        original.push_back(static_cast<unsigned char>(c));
    }

    // --- Comprair usando Run-Length Encoding ---

    std::vector<char> compressed;
    for (size_t i = 0; i < original.size(); ) {
        char current_char = original[i];
        int char_count = 1;

        // Contar repetições sequenciais
        while (i + char_count < original.size() && original[i + char_count] == current_char) {
            char_count++;
        }

        compressed.push_back(static_cast<unsigned char>(current_char));
        compressed.push_back(static_cast<unsigned char>(char_count));
        i += char_count;
    }

    // Escrever os bytes comprimidos em arquivo pra arquivo de string
    outputFile.open("comprimido.bin", std::ios::binary | std::ios::ate);
    size_t size = compressed.size();
    outputFile.write(compressed.data(), size);
    outputFile.close();

    // --- Criar uma função de leitura (assim como pedido) ---

    // Simular leitura dos comprimidos num array externo
    std::vector<char> lido_externamente = {
        static_cast<char>('G'), static_cast<char>(1),
        static_cast<char>('r'), static_cast<char>(1),
        static_cast<char>('o'), static_cast<char>(1),
        static_cast<char>('p'), static_cast<char>(1),
        static_cast<char>('i'), static_cast<char>(1),
        static_cast<char>('s'), static_cast<char>(1),
        static_cast<char>('j'), static_cast<char>(2),
        static_cast<char>('k'), static_cast<char>(2),
        static_cast<char>('l'), static_cast<char>(2),
        static_cast<char>('m'), static_cast<char>(3)
    };

    std::cout << "Bytes comprimidos no array: ";
    for (char c : lido_externamente) {
        printf(" %02X", static_cast<unsigned>(c));
    }
    std::cout << std::endl;

    // Funcionalidade de leitura
    std::vector<unsigned char> reconstruido = decompressVector(lido_externamente);

    if (reconstruido == original) {
        std::cout << "✅ Leitura confere com o arquivo original!" << std::endl;
    } else {
        std::cout << "❌ Leitura falhou." << std::endl;
    }

    return 0;
}
```

